INSERT INTO jlpt_grammar (pattern, meaning_ko, meaning_ja, jlpt_level, formation, formation_detail, category, example_sentences, usage_notes, sort_order) VALUES
('〜べく', '~하기 위해', '目的を表す硬い表現。「〜するために」のかたい言い方。', 'N1', '動詞辞書形 + べく', '동사 사전형 + べく (する는 すべく도 가능). 문어적·격식체.', 'formal', '[{"ja": "問題を解決すべく、専門チームを編成した。", "ko": "문제를 해결하기 위해 전문팀을 편성했다.", "highlight": "解決すべく"}]', 'IT현장: 보고서·기획서 등 문어체에 사용. 「品質を向上させるべく」', 101),
('〜べからず', '~해서는 안 된다(금지)', '禁止を表す。掲示や注意書きに使う古風な表現。', 'N1', '動詞辞書形 + べからず', '동사 사전형 + べからず. 게시·경고문 등에 쓰는 고풍스러운 금지.', 'obligation', '[{"ja": "関係者以外、立ち入るべからず。", "ko": "관계자 외 출입 금지.", "highlight": "立ち入るべからず"}]', '게시문·표어에 주로 사용. 회화에선 거의 안 씀.', 102),
('〜まじき', '~해서는 안 될(자격)', 'あってはならない、ふさわしくない意を表す。', 'N1', '動詞辞書形 + まじき + 名詞', '동사 사전형 + まじき + 명사. 「あるまじき」 형태로 자주 쓰임.', 'obligation', '[{"ja": "それは技術者にあるまじき行為だ。", "ko": "그것은 기술자로서 해서는 안 될 행위다.", "highlight": "あるまじき"}]', '비판·평가 문맥. 「〜にあるまじき」 관용 표현.', 103),
('〜にたえない', '~를 견딜 수 없다 / 차마 ~할 수 없다', '我慢できない、または感情が強くてそうせずにいられない。', 'N1', '動詞辞書形 / 名詞 + にたえない', '①가치: 「見るにたえない(차마 못 볼 정도)」 ②감정: 「感謝にたえない」.', 'degree', '[{"ja": "あまりにひどい出来で、見るにたえない。", "ko": "너무 형편없어서 차마 볼 수 없다.", "highlight": "見るにたえない"}]', '부정적 평가 또는 격식 감사. 「感謝にたえません」', 104),
('〜きらいがある', '~하는 경향이 있다(부정적)', '好ましくない傾向があることを表す。', 'N1', '動詞辞書形 / 名詞の + きらいがある', '바람직하지 않은 성향. 주로 부정적 평가.', 'manner', '[{"ja": "彼は物事を大げさに言うきらいがある。", "ko": "그는 일을 과장해서 말하는 경향이 있다.", "highlight": "言うきらいがある"}]', '사람의 결점·성향 지적에 사용.', 105),
('〜が早いか', '~하자마자', '一つの動作の直後に次が起こる。', 'N1', '動詞辞書形 + が早いか', '거의 동시. 「〜や否や」와 유사하나 더 즉각적.', 'time', '[{"ja": "ベルが鳴るが早いか、彼は部屋を飛び出した。", "ko": "벨이 울리자마자 그는 방을 뛰쳐나갔다.", "highlight": "鳴るが早いか"}]', '문어적. 예상외로 빠른 반응 묘사.', 106),
('〜や否や', '~하자마자', '動作の直後に別のことが起こる。', 'N1', '動詞辞書形 + や否や', '「や」만으로도 쓰임. 문어체.', 'time', '[{"ja": "発表されるや否や、注文が殺到した。", "ko": "발표되자마자 주문이 쇄도했다.", "highlight": "発表されるや否や"}]', '뉴스·서술 문체에 적합.', 107),
('〜そばから', '~하는 족족 / ~하기가 무섭게', '〜してもすぐに繰り返し別のことが起こる。', 'N1', '動詞辞書形 / た形 + そばから', '반복적으로 곧바로 무위가 됨(주로 부정적).', 'time', '[{"ja": "覚えるそばから忘れてしまう。", "ko": "외우는 족족 잊어버린다.", "highlight": "覚えるそばから"}]', '노력이 무색해지는 반복 상황.', 108),
('〜なり〜なり', '~든지 ~든지', 'いくつかの中から選ぶことを示す。', 'N1', '動詞辞書形 / 名詞 + なり〜なり', '예시적 선택지 제시. 「メールなり電話なり」.', 'listing', '[{"ja": "メールなり電話なり、都合のいい方法で連絡してください。", "ko": "메일이든 전화든 편한 방법으로 연락 주세요.", "highlight": "メールなり電話なり"}]', '제안·지시. 「〜なり何なり」도 자주.', 109),
('〜であれ〜であれ', '~든 ~든', 'どちらの場合でも結論は同じ。', 'N1', '名詞 + であれ + 名詞 + であれ', '대비되는 명사 나열, 결론 동일.', 'contrast', '[{"ja": "賛成であれ反対であれ、理由を述べてほしい。", "ko": "찬성이든 반대든 이유를 말해 주길 바란다.", "highlight": "賛成であれ反対であれ"}]', '「〜であろうと〜であろうと」와 유사.', 110),
('〜といい〜といい', '~며 ~며 (모두)', '二つの面を挙げて全体を評価する。', 'N1', '名詞 + といい + 名詞 + といい', '두 측면을 들어 전체를 평가(감탄·비판).', 'listing', '[{"ja": "デザインといい性能といい、申し分ない製品だ。", "ko": "디자인이며 성능이며 나무랄 데 없는 제품이다.", "highlight": "デザインといい性能といい"}]', '평가 문맥. 화자의 감상이 들어감.', 111),
('〜にあって', '~에 있어서 / ~라는 상황에서', '特別な状況・場所・時を強調する。', 'N1', '名詞 + にあって', '특수한 시기·상황 강조(격식).', 'formal', '[{"ja": "非常時にあって、冷静な判断が求められる。", "ko": "비상시에 있어 냉정한 판단이 요구된다.", "highlight": "非常時にあって"}]', '연설·문어. 시대·국면 강조.', 112),
('〜とあれば', '~라면 (특별한 사정이라면)', '特別な条件なら当然そうするという意。', 'N1', '名詞 / 動詞普通形 + とあれば', '특별한 사정이면 당연히. 강한 의지·당위.', 'condition', '[{"ja": "お客様のためとあれば、徹夜も厭わない。", "ko": "고객을 위해서라면 밤샘도 마다하지 않는다.", "highlight": "ためとあれば"}]', '결의 표명. IT현장: 납기·고객 대응 맥락.', 113),
('〜たところで', '~해 봤자', 'たとえ〜しても無駄だという意。', 'N1', '動詞た形 + ところで', '역접·무용. 뒤에 부정적 결과.', 'contrast', '[{"ja": "今さら謝ったところで、信頼は戻らない。", "ko": "이제 와서 사과해 봤자 신뢰는 돌아오지 않는다.", "highlight": "謝ったところで"}]', '체념·단정 어조.', 114),
('〜ものを', '~할 것을 (그랬다면 좋았을 텐데)', '残念・不満の気持ちを表す。', 'N1', '普通形 + ものを', '아쉬움·원망. 문말에도 옴.', 'contrast', '[{"ja": "早く言ってくれればよかったものを。", "ko": "일찍 말해 줬으면 좋았을 것을.", "highlight": "よかったものを"}]', '비난·아쉬움이 섞인 회화.', 115),
('〜といえども', '~라 할지라도', 'たとえ〜でも、という逆接の硬い表現。', 'N1', '名詞 / 普通形 + といえども', '「〜でも」의 격식·문어체.', 'contrast', '[{"ja": "専門家といえども、間違えることはある。", "ko": "전문가라 할지라도 틀릴 때가 있다.", "highlight": "専門家といえども"}]', '문어·연설.', 116),
('〜ながらに', '~한 채로 / ~그대로', 'その状態のままであることを表す。', 'N1', '名詞 / 動詞ます形 + ながらに', '「生まれながらに」「涙ながらに」 등 관용적.', 'manner', '[{"ja": "彼女は涙ながらに事情を説明した。", "ko": "그녀는 눈물을 흘리며 사정을 설명했다.", "highlight": "涙ながらに"}]', '관용 표현 위주. 「昔ながらの」(형용).', 117),
('〜きっての', '~중 으뜸가는', 'ある範囲で最もすぐれた、の意。', 'N1', '名詞 + きっての + 名詞', '어떤 범위 내 최고. 「業界きっての」.', 'degree', '[{"ja": "彼は社内きってのエンジニアだ。", "ko": "그는 사내 최고의 엔지니어다.", "highlight": "社内きっての"}]', '칭찬·소개. IT현장 인물 소개에 적합.', 118),
('〜の至り', '~의 극치 (~하기 그지없음)', '感情が極限であることを表す格式表現。', 'N1', '名詞 + の至り', '「光栄の至り」「赤面の至り」 등.', 'degree', '[{"ja": "このような賞をいただき、光栄の至りです。", "ko": "이런 상을 받게 되어 영광스럽기 그지없습니다.", "highlight": "光栄の至り"}]', '격식 인사·수상 소감.', 119),
('〜の極み', '~의 극치', '程度が極限であることを表す。', 'N1', '名詞 + の極み', '「贅沢の極み」「疲労の極み」 등.', 'degree', '[{"ja": "連日の残業で疲労の極みに達した。", "ko": "연일 야근으로 피로의 극에 달했다.", "highlight": "疲労の極み"}]', '강한 정도 강조(긍·부정 모두).', 120),
('〜限りだ', '~하기 그지없다', '話し手の強い感情を表す。', 'N1', 'い形容詞 / な形容詞な + 限りだ', '감정 형용사에 붙어 극한 감정.', 'degree', '[{"ja": "一人で海外赴任とは、心細い限りだ。", "ko": "혼자 해외 부임이라니 불안하기 그지없다.", "highlight": "心細い限りだ"}]', '주관적 감정 강조.', 121),
('〜始末だ', '(결국) ~하는 지경이다', '悪い経過の末に至った結果を表す。', 'N1', '動詞辞書形 + 始末だ', '나쁜 경과의 결말(부정적).', 'change', '[{"ja": "納期は遅れ、ついに客先で謝罪する始末だ。", "ko": "납기는 늦어지고 결국 고객사에서 사과하는 지경이다.", "highlight": "謝罪する始末だ"}]', '부정적 귀결 서술. 「あげくの果てに〜始末だ」', 122),
('〜ずくめ', '~일색 / 온통 ~', '同じものや事柄ばかりであること。', 'N1', '名詞 + ずくめ', '「いいことずくめ」「黒ずくめ」.', 'manner', '[{"ja": "今年はいいことずくめの一年だった。", "ko": "올해는 좋은 일만 가득한 한 해였다.", "highlight": "いいことずくめ"}]', '한정된 명사와 결합하는 관용.', 123),
('〜まみれ', '~투성이', '汚いものが一面に付着している状態。', 'N1', '名詞 + まみれ', '「泥まみれ」「血まみれ」 등 더러움.', 'manner', '[{"ja": "作業を終えた彼は汗まみれだった。", "ko": "작업을 마친 그는 땀투성이였다.", "highlight": "汗まみれ"}]', '주로 액체·먼지 등 부정적 부착.', 124),
('〜ことなしに', '~하지 않고는', '〜しないで、の硬い言い方。', 'N1', '動詞辞書形 + ことなしに', '「〜なしに」의 동사형. 문어.', 'manner', '[{"ja": "努力することなしに成功は得られない。", "ko": "노력하지 않고는 성공을 얻을 수 없다.", "highlight": "努力することなしに"}]', '문어·논설.', 125),
('〜をおいて', '~외에는 (없다)', 'それ以外にないと強調する。', 'N1', '名詞 + をおいて 〜ない', '유일성 강조. 뒤에 부정.', 'emphasis', '[{"ja": "この役を任せられるのは彼をおいて他にいない。", "ko": "이 역할을 맡길 사람은 그 말고는 없다.", "highlight": "彼をおいて"}]', '인물·대상의 유일함 강조.', 126),
('〜にかたくない', '~하기 어렵지 않다 (충분히 ~할 수 있다)', '容易に〜できる、の意。', 'N1', '名詞 / 動詞辞書形 + にかたくない', '「想像にかたくない」 관용.', 'ability', '[{"ja": "彼の苦労は想像にかたくない。", "ko": "그의 고생은 충분히 짐작할 수 있다.", "highlight": "想像にかたくない"}]', '주로 「想像/察する」와 결합.', 127),
('〜にひきかえ', '~와는 반대로', '二つを対比して大きく違うことを示す。', 'N1', '名詞 + にひきかえ', '대조·대비(주관적 평가 포함).', 'contrast', '[{"ja": "昨年の不振にひきかえ、今年は絶好調だ。", "ko": "작년의 부진과는 반대로 올해는 절호조다.", "highlight": "不振にひきかえ"}]', '대비 강조. 「〜に比べて」보다 주관적.', 128),
('〜にもまして', '~보다 더욱, 그 이상으로', 'それ以上に程度が高いことを表す。', 'N1', '名詞 + にもまして', '「以前にもまして」「何にもまして」.', 'contrast', '[{"ja": "以前にもまして業務が忙しくなった。", "ko": "이전보다 더욱 업무가 바빠졌다.", "highlight": "以前にもまして"}]', '비교 강조.', 129),
('〜はおろか', '~는커녕', '〜はもちろん、より程度の低いことさえ、の意。', 'N1', '名詞 + はおろか', '뒤에 「〜も〜ない」가 자주. 부정 강조.', 'emphasis', '[{"ja": "海外はおろか、国内旅行さえしたことがない。", "ko": "해외는커녕 국내 여행조차 한 적이 없다.", "highlight": "海外はおろか"}]', '극단 대비로 강조.', 130);
INSERT INTO jlpt_vocabulary (word, reading, meaning_ko, jlpt_level, part_of_speech, example_sentence, example_sentence_ko) VALUES
('妥協', 'だきょう', '타협', 'N1', '명사', '双方が妥協して合意に達した。', '양측이 타협하여 합의에 이르렀다.'),
('軋轢', 'あつれき', '알력, 불화', 'N1', '명사', '部署間の軋轢が表面化した。', '부서 간 알력이 표면화되었다.'),
('隔たり', 'へだたり', '격차, 거리', 'N1', '명사', '理想と現実には大きな隔たりがある。', '이상과 현실에는 큰 격차가 있다.'),
('名残', 'なごり', '자취, 여운', 'N1', '명사', '町には城下町の名残が残っている。', '마을에는 성하 마을의 자취가 남아 있다.'),
('措置', 'そち', '조치', 'N1', '명사', '再発防止の措置を講じた。', '재발 방지 조치를 강구했다.'),
('趨勢', 'すうせい', '추세', 'N1', '명사', '市場の趨勢を見極める必要がある。', '시장의 추세를 가늠할 필요가 있다.'),
('帰結', 'きけつ', '귀결', 'N1', '명사', '当然の帰結としてコストが増えた。', '당연한 귀결로 비용이 늘었다.'),
('真偽', 'しんぎ', '진위', 'N1', '명사', '情報の真偽を確かめる。', '정보의 진위를 확인한다.'),
('顛末', 'てんまつ', '전말', 'N1', '명사', '事故の顛末を報告書にまとめた。', '사고의 전말을 보고서에 정리했다.'),
('内訳', 'うちわけ', '내역', 'N1', '명사', '費用の内訳を提示してください。', '비용의 내역을 제시해 주세요.'),
('相違', 'そうい', '상위, 차이', 'N1', '명사', '両者の見解には相違がある。', '양측의 견해에는 차이가 있다.'),
('遜色', 'そんしょく', '손색', 'N1', '명사', '海外製品と比べても遜色ない。', '해외 제품과 비교해도 손색이 없다.'),
('拍車', 'はくしゃ', '박차', 'N1', '명사', '需要の増加が開発に拍車をかけた。', '수요 증가가 개발에 박차를 가했다.'),
('端緒', 'たんしょ', '단서, 실마리', 'N1', '명사', 'この発見が解決の端緒となった。', '이 발견이 해결의 실마리가 되었다.'),
('様相', 'ようそう', '양상', 'N1', '명사', '事態は深刻な様相を呈してきた。', '사태는 심각한 양상을 띠기 시작했다.'),
('痕跡', 'こんせき', '흔적', 'N1', '명사', '不正アクセスの痕跡が見つかった。', '부정 접근의 흔적이 발견되었다.'),
('真髄', 'しんずい', '진수', 'N1', '명사', '職人技の真髄に触れた。', '장인 기술의 진수를 접했다.'),
('醍醐味', 'だいごみ', '묘미', 'N1', '명사', '開発の醍醐味は問題を解く瞬間にある。', '개발의 묘미는 문제를 푸는 순간에 있다.'),
('布石', 'ふせき', '포석', 'N1', '명사', '将来の事業拡大に向けた布石を打つ。', '미래 사업 확장을 위한 포석을 둔다.'),
('担保', 'たんぽ', '담보', 'N1', '명사', '品質を担保する仕組みが必要だ。', '품질을 담보하는 체계가 필요하다.'),
('凌ぐ', 'しのぐ', '능가하다, 견뎌내다', 'N1', '동사', '新製品は従来品を凌ぐ性能だ。', '신제품은 기존 제품을 능가하는 성능이다.'),
('葬る', 'ほうむる', '매장하다, 묻어버리다', 'N1', '동사', '不都合な事実を闇に葬る。', '불리한 사실을 어둠에 묻어버린다.'),
('顧みる', 'かえりみる', '되돌아보다, 돌보다', 'N1', '동사', '一年の活動を顧みる。', '한 해의 활동을 되돌아본다.'),
